VALUES (4, 'True or False: Client computers on a client/server network share their resources directly with each other.', 'A. True', 'B. False', 'C. Only in large networks', 'D. Only if configured by the server', 'B', 'Clients communicate through the server, which manages resource sharing.', 'medium');
