VALUES (4, 'True or False: M2M communication is limited to local networks and cannot function over the Internet.', 'A. True', 'B. False', '', '', 'B', 'M2M communication can function over LAN, WAN, or even across the globe via the Internet using device servers and serial tunneling.', 'medium');
